@Service
public class OrderFacade {
    private final UserRepository userRepository;
    private final OrderRepository orderRepository;
    private final EmailNotifier emailNotifier;
    private final PaymentProcessor paymentProcessor;

    @Autowired
    public OrderFacade(UserRepository userRepository, OrderRepository orderRepository,
                       EmailNotifier emailNotifier, PaymentProcessor paymentProcessor) {
        this.userRepository = userRepository;
        this.orderRepository = orderRepository;
        this.emailNotifier = emailNotifier;
        this.paymentProcessor = paymentProcessor;
    }

    // Facade method that simplifies the order placement process
    public boolean placeOrder(Long userId, OrderRequest request) {
        User user = userRepository.findById(userId);

        Order order = createOrderFromRequest(request, user);
        boolean paymentSuccessful = paymentProcessor.processPayment(order);

        if (paymentSuccessful) {
            orderRepository.save(order);
            emailNotifier.sendOrderConfirmation(order);
            return true;
        }

        return false;
    }

    private Order createOrderFromRequest(OrderRequest request, User user) {
        // Map from request to Order entity
        return new Order(user, request.getItems(), request.getShippingAddress());
    }
}

