        System.out.println("Cannot ship a new order - must process first");
    }

    @Override
    public String getStatus() {
        return "NEW";
    }
}

@Component
public class ProcessingOrderState implements OrderState {
    @Override
    public void process(OrderContext context) {
        System.out.println("Order is already being processed");
    }

    @Override
    public void cancel(OrderContext context) {
        System.out.println("Cancelling processing order");
        context.setState(context.getCancelledState());
    }

    @Override
    public void ship(OrderContext context) {
        System.out.println("Shipping order");
        context.setState(context.getShippedState());
    }

    @Override
    public String getStatus() {
        return "PROCESSING";
    }
}

