// Context
@Component
public class OrderContext {
    @Autowired private NewOrderState newState;
    @Autowired private ProcessingOrderState processingState;
    @Autowired private ShippedOrderState shippedState;
    @Autowired private CancelledOrderState cancelledState;

    private OrderState currentState;
    private String orderId;

    // Initialize with new state when an order is created
    public void createOrder(String orderId) {
        this.orderId = orderId;
        this.currentState = newState;
    }

    // Methods that delegate to the current state
    public void processOrder() {
        currentState.process(this);
    }

    public void cancelOrder() {
        currentState.cancel(this);
    }

    public void shipOrder() {
        currentState.ship(this);
    }

    public String getOrderStatus() {
        return currentState.getStatus();
    }

    // State change method
    public void setState(OrderState state) {
        this.currentState = state;
    }

    // Getter methods for states
    public NewOrderState getNewState() {
        return newState;
    }

    public ProcessingOrderState getProcessingState() {
        return processingState;
    }

    public ShippedOrderState getShippedState() {
        return shippedState;
    }

    public CancelledOrderState getCancelledState() {
        return cancelledState;
    }
}

