public interface DocumentVisitor {
    void visit(TextElement element);
    void visit(ImageElement element);
    void visit(TableElement element);
}

@Component
public class HTMLExportVisitor implements DocumentVisitor {
    private StringBuilder html = new StringBuilder();

    @Override
    public void visit(TextElement element) {
        html.append("<p>").append(element.getText()).append("</p>\n");
    }

    @Override
    public void visit(ImageElement element) {
        html.append("<img src=\"").append(element.getSource())
            .append("\" width=\"").append(element.getWidth())
            .append("\" height=\"").append(element.getHeight())
            .append("\" />\n");
    }

    @Override
    public void visit(TableElement element) {
        html.append("<table>\n");
        // Table rendering logic
        html.append("</table>\n");
    }

    public String getHTML() {
        return html.toString();
    }
}

@Component
public class MarkdownExportVisitor implements DocumentVisitor {
    private StringBuilder markdown = new StringBuilder();

    @Override
    public void visit(TextElement element) {
        markdown.append(element.getText()).append("\n\n");
    }

    @Override
    public void visit(ImageElement element) {
        markdown.append("![image](").append(element.getSource()).append(")\n\n");
    }

    @Override
    public void visit(TableElement element) {
        // Markdown table rendering logic
    }

    public String getMarkdown() {
        return markdown.toString();
    }
}

// Using the visitors
@Service
public class DocumentExportService {
    @Autowired
    private HTMLExportVisitor htmlExporter;

    @Autowired
    private MarkdownExportVisitor markdownExporter;

    public String exportToHTML(List<DocumentElement> document) {
        for (DocumentElement element : document) {
            element.accept(htmlExporter);
        }
        return htmlExporter.getHTML();
    }

    public String exportToMarkdown(List<DocumentElement> document) {
        for (DocumentElement element : document) {
            element.accept(markdownExporter);
        }
        return markdownExporter.getMarkdown();
    }
}

